pragma language_version 0.23;
import CompactStandardLibrary;

export ledger authorizedCommitments: HistoricMerkleTree<10, Bytes<32>>;
export ledger spentNullifiers: Set<Bytes<32>>;
export ledger voteCommitments: MerkleTree<10, Bytes<32>>;

witness findAuthPath(pk: Bytes<32>): MerkleTreePath<10, Bytes<32>>;
witness secretKey(): Bytes<32>;

circuit nullifier(round: Uint<64>, sk: Bytes<32>): Bytes<32> {
  const roundBytes = round as Bytes<32>;
  return persistentHash<Vector<3, Bytes<32>>>([pad(32, "cryptoguardians:nullifier"), roundBytes, sk]);
}

export circuit castVote(pk: Bytes<32>, round: Uint<64>, vote: Bytes<32>, randomness: Bytes<32>): [] {
  const authPath = findAuthPath(pk);
  assert(authPath.leaf == pk, "La ruta no coincide con la clave pública");
  assert(authorizedCommitments.checkRoot(disclose(merkleTreePathRoot<10, Bytes<32>>(authPath))), "La raíz de autorización no es válida");
  const nul = nullifier(round, secretKey());
  assert(!spentNullifiers.member(disclose(nul)), "Ya se votó en esta ronda");
  voteCommitments.insert(persistentCommit<Bytes<32>>(vote, randomness));
  spentNullifiers.insert(disclose(nul));
}

// La prueba de elegibilidad usa membresía ___ sin revelar la hoja coincidente.
export circuit verifyVoteOpening(commitment: Bytes<32>, vote: Bytes<32>, randomness: Bytes<32>): [] {
  assert(persistentCommit<Bytes<32>>(vote, randomness) == commitment, "La apertura del voto no es válida");
}

